	static Stream<Arguments> explanations() {
		return Stream.of(DISTINCT, GROUP)
				.flatMap(query -> Stream.of(false, true).map(inferred -> Arguments.of(query, inferred)));
	}

	@ParameterizedTest(name = "{0} (inferred={1})")
	@MethodSource("explanations")
	void explanationReportsStatementAndGroupWork(String query, boolean inferred) {
		SailRepository repository = openRepository(inferred);
		try (var connection = repository.getConnection()) {
			var tupleQuery = connection.prepareTupleQuery(query);
			tupleQuery.setIncludeInferred(inferred);
			long opened = LmdbPrefixRunPlan.OPENED.get();
			long scanned = LmdbPrefixRunPlan.ROWS_SCANNED.get();
			GenericPlanNode plan = tupleQuery.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			long expectedResults = inferred ? 3 : 2;
			assertThat(plan.getResultSizeActual()).isEqualTo(expectedResults);
			assertThat(LmdbPrefixRunPlan.OPENED.get() - opened).isEqualTo(inferred ? 2 : 1);
			var statement = nodes(plan).filter(node -> node.getType().startsWith("StatementPattern"))
					.findFirst()
					.orElseThrow();
			assertThat(statement.getSourceRowsScannedActual()).as("statement source rows scanned").isPositive();
			assertThat(statement.getSourceRowsScannedActual())
					.isEqualTo(LmdbPrefixRunPlan.ROWS_SCANNED.get() - scanned);
			assertThat(statement.getStringMetricActual(TelemetryMetricNames.INDEX_NAME)).isEqualTo("posc");
			assertThat(statement.getLongMetricActual(TelemetryMetricNames.INDEX_LOOKUP_COUNT_ACTUAL)).isEqualTo(1);
			if (query.equals(GROUP)) {
				var group = nodes(plan).filter(node -> node.getType().startsWith("Group ("))
						.findFirst()
						.orElseThrow();
				assertThat(group.getLongMetricActual(TelemetryMetricNames.GROUPS_CREATED_ACTUAL))
						.isEqualTo(expectedResults);
				assertThat(group.getLongMetricActual(TelemetryMetricNames.AGGREGATE_EVAL_COUNT_ACTUAL))
						.isEqualTo(expectedResults);
				assertThat(group.getLongMetricActual(TelemetryMetricNames.MAX_GROUP_SIZE_ACTUAL))
						.isEqualTo(inferred ? 5 : 3);
				assertThat(group.getDoubleMetricActual(TelemetryMetricNames.AVG_GROUP_SIZE_ACTUAL))
						.isEqualTo((inferred ? 7 : 4) / (double) expectedResults);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static Stream<GenericPlanNode> nodes(GenericPlanNode node) {
		List<GenericPlanNode> children = node.getPlans();
		return children == null ? Stream.of(node)
				: Stream.concat(Stream.of(node), children.stream().flatMap(LmdbIndexedQueryLifecycleTest::nodes));
	}

	private SailRepository openRepository(boolean inferred) {
		var config = new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false);
		var store = new LmdbStore(dataDir.toFile(), config);
		var repository = new SailRepository(store);
		repository.init();
		var vf = repository.getValueFactory();
		var first = vf.createIRI("urn:p1");
		var second = vf.createIRI("urn:p2");
		var subject = vf.createIRI("urn:s1");
		var object = vf.createIRI("urn:o1");
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(subject, first, object);
			connection.add(subject, first, object, vf.createIRI("urn:explicitGraph"));
			connection.add(vf.createIRI("urn:s2"), first, object);
			connection.add(subject, second, object);
			connection.commit();
		}
		if (inferred) {
			try (var connection = (InferencerConnection) store.getConnection()) {
				connection.begin();
				connection.addInferredStatement(subject, first, object, vf.createIRI("urn:inferredGraph"));
				connection.addInferredStatement(subject, first, object, vf.createIRI("urn:otherInferredGraph"));
				connection.addInferredStatement(subject, vf.createIRI("urn:p3"), object);
				connection.commit();
			}
		}
		return repository;
	}

	private static <T> FutureTask<T> startDaemon(Callable<T> action) {
		FutureTask<T> task = new FutureTask<>(action);
		Thread.ofPlatform().daemon().start(task);
		return task;
	}
